31	    30	async function request<T>(path: string, init?: RequestInit): Promise<T> {
32	    31	  let res: Response
33	    32	  try {
34	    33	    res = await fetch(`/api${path}`, {
35	    34	      ...init,
36	    35	      headers: { 'Content-Type': 'application/json', ...init?.headers },
37	    36	    })
38	    37	  } catch (e) {
39	    38	    throw new ApiError(0, e instanceof Error ? e.message : 'network error')
40	    39	  }
41	    40	  if (!res.ok) {
42	    41	    throw new ApiError(res.status, await detail(res))
43	    42	  }
44	    43	  if (res.status === 204) {
45	    44	    return undefined as T
46	    45	  }
47	    46	  return (await res.json()) as T
48	    47	}
49	    48	
50	    49	async function detail(res: Response): Promise<string> {
51	    50	  try {
52	    51	    const body = (await res.json()) as { detail?: unknown }
53	    52	    if (typeof body.detail === 'string') return body.detail
54	    53	  } catch {
55	    54	    // Non-JSON error body (proxy/nginx 502 etc.) — fall through to the status.
56	    55	  }
57	    56	  return `HTTP ${res.status}`
58	    57	}
