215	     1	// The one realtime composable: it owns the SSE connection to /api/events and
216	     2	// its reconnect, and stores subscribe to it — no component ever opens a socket
217	     3	// itself (frontend-vue rule). The connection is a module singleton so every
218	     4	// store shares one EventSource.
219	     5	//
220	     6	// Native EventSource rather than VueUse useEventSource on purpose: useEventSource
221	     7	// exposes only "latest value" refs (event/data are shallowRefs), so watching the
222	     8	// event name drops two consecutive same-named events (two stock_changed in a row
223	     9	// would deliver one callback). addEventListener fires per event, which is what
224	    10	// live updates need. The browser's EventSource auto-reconnects, so no retry loop
225	    11	// is needed here (see DECISIONS.md).
226	    12	
227	    13	export const REALTIME_EVENTS = ['stock_changed', 'sale_status', 'order_status'] as const
228	    14	export type RealtimeEvent = (typeof REALTIME_EVENTS)[number]
229	    15	
230	    16	type Listener = (data: unknown) => void
231	    17	
232	    18	interface RealtimeConnection {
233	    19	  source: EventSource
234	    20	  listeners: Map<RealtimeEvent, Set<Listener>>
235	    21	  reconnectListeners: Set<() => void>
236	    22	}
237	    23	
238	    24	export interface Realtime {
239	    25	  on(event: RealtimeEvent, listener: Listener): void
240	    26	  onReconnect(listener: () => void): void
241	    27	}
242	    28	
243	    29	let connection: RealtimeConnection | null = null
244	    30	
245	    31	function parse(data: string): unknown {
246	    32	  try {
247	    33	    return JSON.parse(data)
248	    34	  } catch {
249	    35	    return null
250	    36	  }
251	    37	}
252	    38	
253	    39	export function useRealtime(): Realtime {
254	    40	  if (!connection) {
255	    41	    const listeners = new Map<RealtimeEvent, Set<Listener>>()
256	    42	    const reconnectListeners = new Set<() => void>()
257	    43	    const source = new EventSource('/api/events')
258	    44	
259	    45	    for (const name of REALTIME_EVENTS) {
260	    46	      source.addEventListener(name, (event: MessageEvent) => {
261	    47	        const payload = parse(event.data)
262	    48	        for (const listener of listeners.get(name) ?? []) listener(payload)
263	    49	      })
264	    50	    }
265	    51	
266	    52	    // The first open is the initial connection; each later open is a reconnect,
267	    53	    // so refetch before resuming the stream (a missed event is never shown).
268	    54	    let opened = false
269	    55	    source.onopen = () => {
270	    56	      if (opened) {
271	    57	        for (const listener of reconnectListeners) listener()
272	    58	      }
273	    59	      opened = true
274	    60	    }
275	    61	
276	    62	    connection = { source, listeners, reconnectListeners }
277	    63	  }
278	    64	  const conn = connection
279	    65	  return {
280	    66	    on(event, listener) {
281	    67	      const set = conn.listeners.get(event) ?? new Set<Listener>()
282	    68	      set.add(listener)
283	    69	      conn.listeners.set(event, set)
284	    70	    },
285	    71	    onReconnect(listener) {
286	    72	      conn.reconnectListeners.add(listener)
287	    73	    },
288	    74	  }
289	    75	}
