351	     9	// Per-reservation checkout state. The idempotency key and the order id are
352	    10	// created once and reused across retries, so a double click or a "try again"
353	    11	// never creates a second order (the backend also enforces this, but the client
354	    12	// does not rely on that alone).
355	    13	export interface Checkout {
356	    14	  key: string
357	    15	  orderId: number | null
358	    16	  busy: boolean
359	    17	  outcome: PaymentOutcome | null
360	    18	  error: string | null
361	    19	}
362	    20	
363	    21	// The idempotency key + order id survive a reload in sessionStorage, so a
364	    22	// "try again" after a decline reuses the existing order instead of creating a
365	    23	// second one (which the backend's UNIQUE(reservation_id) would reject).
366	    24	const CHECKOUT_STORAGE = 'lastunit:checkouts'
367	    25	
368	    26	interface PersistedCheckout {
369	    27	  key: string
370	    28	  orderId: number | null
371	    29	}
372	    30	
373	    31	function loadCheckouts(): Record<number, Checkout> {
374	    32	  try {
375	    33	    const raw = sessionStorage.getItem(CHECKOUT_STORAGE)
376	    34	    if (!raw) return {}
377	    35	    const saved = JSON.parse(raw) as Record<string, PersistedCheckout>
378	    36	    const restored: Record<number, Checkout> = {}
379	    37	    for (const [id, value] of Object.entries(saved)) {
380	    38	      restored[Number(id)] = { ...value, busy: false, outcome: null, error: null }
381	    39	    }
382	    40	    return restored
383	    41	  } catch {
384	    42	    return {}
385	    43	  }
386	    44	}
387	    45	
388	    46	function persistCheckouts(checkouts: Record<number, Checkout>): void {
389	    47	  try {
390	    48	    const slim: Record<number, PersistedCheckout> = {}
391	    49	    for (const [id, checkout] of Object.entries(checkouts)) {
392	    50	      slim[Number(id)] = { key: checkout.key, orderId: checkout.orderId }
393	    51	    }
394	    52	    sessionStorage.setItem(CHECKOUT_STORAGE, JSON.stringify(slim))
395	    53	  } catch {
396	    54	    // sessionStorage can be unavailable (private mode); the in-memory copy works.
397	    55	  }
398	    56	}
