516	    16	  // and sale_status (sale end), so refetch on any of them.
517	    17	  async function applyEvent(event: RealtimeEvent): Promise<void> {
518	    18	    if (
519	    19	      event !== 'order_status' &&
520	    20	      event !== 'stock_changed' &&
521	    21	      event !== 'sale_status'
522	    22	    )
523	    23	      return
