537	    37	    rt.on('stock_changed', () => void applyEvent('stock_changed'))
538	    38	    rt.on('sale_status', () => void applyEvent('sale_status'))
539	    39	    rt.onReconnect(() => void fetchOrders())
540	    40	  }
