     1	// The single place that talks HTTP. Every request goes through the /api
     2	// prefix so the Vite dev proxy and nginx route it to the backend without the
     3	// browser knowing the origin; components and stores never call fetch directly.
     4	//
     5	// Session auth rides the HttpOnly cookie, so no token is threaded through
     6	// here — the browser sends it on same-origin requests (the default
     7	// `credentials` of 'same-origin').
     8	
     9	import type {
    10	  Cart,
    11	  Order,
    12	  PayResult,
    13	  Reservation,
    14	  Sale,
    15	  SaleCreateInput,
    16	  SaleStats,
    17	  User,
    18	} from './types'
    19	
    20	export class ApiError extends Error {
    21	  readonly status: number
    22	
    23	  constructor(status: number, message: string) {
    24	    super(message)
    25	    this.name = 'ApiError'
    26	    this.status = status
    27	  }
    28	}
    29	
    30	async function request<T>(path: string, init?: RequestInit): Promise<T> {
    31	  let res: Response
    32	  try {
    33	    res = await fetch(`/api${path}`, {
    34	      ...init,
    35	      headers: { 'Content-Type': 'application/json', ...init?.headers },
    36	    })
    37	  } catch (e) {
    38	    throw new ApiError(0, e instanceof Error ? e.message : 'network error')
    39	  }
    40	  if (!res.ok) {
    41	    throw new ApiError(res.status, await detail(res))
    42	  }
    43	  if (res.status === 204) {
    44	    return undefined as T
    45	  }
    46	  return (await res.json()) as T
    47	}
    48	
    49	async function detail(res: Response): Promise<string> {
    50	  try {
    51	    const body = (await res.json()) as { detail?: unknown }
    52	    if (typeof body.detail === 'string') return body.detail
    53	  } catch {
    54	    // Non-JSON error body (proxy/nginx 502 etc.) — fall through to the status.
    55	  }
    56	  return `HTTP ${res.status}`
    57	}
    58	
    59	function post<T>(path: string, body: unknown): Promise<T> {
    60	  return request<T>(path, { method: 'POST', body: JSON.stringify(body) })
    61	}
    62	
    63	export const api = {
    64	  // auth
    65	  register(email: string, password: string): Promise<User> {
    66	    return post<User>('/auth/register', { email, password })
    67	  },
    68	  login(email: string, password: string): Promise<User> {
    69	    return post<User>('/auth/login', { email, password })
    70	  },
    71	  logout(): Promise<void> {
    72	    return request<void>('/auth/logout', { method: 'POST' })
    73	  },
    74	  me(): Promise<User> {
    75	    return request<User>('/auth/me')
    76	  },
    77	
    78	  // sales
    79	  listSales(): Promise<Sale[]> {
    80	    return request<Sale[]>('/sales')
    81	  },
    82	  getSale(id: number): Promise<Sale> {
    83	    return request<Sale>(`/sales/${id}`)
    84	  },
    85	  createSale(input: SaleCreateInput): Promise<Sale> {
    86	    return post<Sale>('/sales', input)
    87	  },
    88	  reserve(saleId: number): Promise<Reservation> {
    89	    return post<Reservation>(`/sales/${saleId}/reserve`, {})
    90	  },
    91	
    92	  // cart
    93	  releaseReservation(reservationId: number): Promise<void> {
    94	    return request<void>(`/reservations/${reservationId}`, { method: 'DELETE' })
    95	  },
    96	  cart(): Promise<Cart> {
    97	    return request<Cart>('/me/cart')
    98	  },
    99	  listOrders(): Promise<Order[]> {
   100	    return request<Order[]>('/me/orders')
   101	  },
   102	
   103	  // orders + payments
   104	  createOrder(reservationId: number, idempotencyKey: string): Promise<Order> {
   105	    return request<Order>('/orders', {
   106	      method: 'POST',
   107	      body: JSON.stringify({ reservation_id: reservationId }),
   108	      headers: { 'Idempotency-Key': idempotencyKey },
   109	    })
   110	  },
   111	  pay(orderId: number, cardNumber: string): Promise<PayResult> {
   112	    return post<PayResult>(`/orders/${orderId}/pay`, { card_number: cardNumber })
   113	  },
   114	
   115	  // shop
   116	  saleStats(saleId: number): Promise<SaleStats> {
   117	    return request<SaleStats>(`/shop/sales/${saleId}/stats`)
   118	  },
   119	  checkPayment(reference: string): Promise<{ status: string }> {
   120	    return post<{ status: string }>(`/shop/payments/${reference}/check`, {})
