     1	// The one realtime composable: it owns the SSE connection to /api/events and
     2	// its reconnect, and stores subscribe to it — no component ever opens a socket
     3	// itself (frontend-vue rule). The connection is a module singleton so every
     4	// store shares one EventSource.
     5	//
     6	// Native EventSource rather than VueUse useEventSource on purpose: useEventSource
     7	// exposes only "latest value" refs (event/data are shallowRefs), so watching the
     8	// event name drops two consecutive same-named events (two stock_changed in a row
     9	// would deliver one callback). addEventListener fires per event, which is what
    10	// live updates need. The browser's EventSource auto-reconnects, so no retry loop
    11	// is needed here (see DECISIONS.md).
    12	
    13	export const REALTIME_EVENTS = ['stock_changed', 'sale_status', 'order_status'] as const
    14	export type RealtimeEvent = (typeof REALTIME_EVENTS)[number]
    15	
    16	type Listener = (data: unknown) => void
    17	
    18	interface RealtimeConnection {
    19	  source: EventSource
    20	  listeners: Map<RealtimeEvent, Set<Listener>>
    21	  reconnectListeners: Set<() => void>
    22	}
    23	
    24	export interface Realtime {
    25	  on(event: RealtimeEvent, listener: Listener): void
    26	  onReconnect(listener: () => void): void
    27	}
    28	
    29	let connection: RealtimeConnection | null = null
    30	
    31	function parse(data: string): unknown {
    32	  try {
    33	    return JSON.parse(data)
    34	  } catch {
    35	    return null
    36	  }
    37	}
    38	
    39	export function useRealtime(): Realtime {
    40	  if (!connection) {
    41	    const listeners = new Map<RealtimeEvent, Set<Listener>>()
    42	    const reconnectListeners = new Set<() => void>()
    43	    const source = new EventSource('/api/events')
    44	
    45	    for (const name of REALTIME_EVENTS) {
    46	      source.addEventListener(name, (event: MessageEvent) => {
    47	        const payload = parse(event.data)
    48	        for (const listener of listeners.get(name) ?? []) listener(payload)
    49	      })
    50	    }
    51	
    52	    // The first open is the initial connection; each later open is a reconnect,
    53	    // so refetch before resuming the stream (a missed event is never shown).
    54	    let opened = false
    55	    source.onopen = () => {
    56	      if (opened) {
    57	        for (const listener of reconnectListeners) listener()
    58	      }
    59	      opened = true
    60	    }
    61	
    62	    connection = { source, listeners, reconnectListeners }
    63	  }
    64	  const conn = connection
    65	  return {
    66	    on(event, listener) {
    67	      const set = conn.listeners.get(event) ?? new Set<Listener>()
    68	      set.add(listener)
    69	      conn.listeners.set(event, set)
    70	    },
    71	    onReconnect(listener) {
    72	      conn.reconnectListeners.add(listener)
    73	    },
    74	  }
    75	}
