     9	// Per-reservation checkout state. The idempotency key and the order id are
    10	// created once and reused across retries, so a double click or a "try again"
    11	// never creates a second order (the backend also enforces this, but the client
    12	// does not rely on that alone).
    13	export interface Checkout {
    14	  key: string
    15	  orderId: number | null
    16	  busy: boolean
    17	  outcome: PaymentOutcome | null
    18	  error: string | null
    19	}
    20	
    21	// The idempotency key + order id survive a reload in sessionStorage, so a
    22	// "try again" after a decline reuses the existing order instead of creating a
    23	// second one (which the backend's UNIQUE(reservation_id) would reject).
    24	const CHECKOUT_STORAGE = 'lastunit:checkouts'
    25	
    26	interface PersistedCheckout {
    27	  key: string
    28	  orderId: number | null
    29	}
    30	
    31	function loadCheckouts(): Record<number, Checkout> {
    32	  try {
    33	    const raw = sessionStorage.getItem(CHECKOUT_STORAGE)
    34	    if (!raw) return {}
    35	    const saved = JSON.parse(raw) as Record<string, PersistedCheckout>
    36	    const restored: Record<number, Checkout> = {}
    37	    for (const [id, value] of Object.entries(saved)) {
    38	      restored[Number(id)] = { ...value, busy: false, outcome: null, error: null }
    39	    }
    40	    return restored
    41	  } catch {
    42	    return {}
    43	  }
    44	}
    45	
    46	function persistCheckouts(checkouts: Record<number, Checkout>): void {
    47	  try {
    48	    const slim: Record<number, PersistedCheckout> = {}
    49	    for (const [id, checkout] of Object.entries(checkouts)) {
    50	      slim[Number(id)] = { key: checkout.key, orderId: checkout.orderId }
    51	    }
    52	    sessionStorage.setItem(CHECKOUT_STORAGE, JSON.stringify(slim))
    53	  } catch {
    54	    // sessionStorage can be unavailable (private mode); the in-memory copy works.
    55	  }
    56	}
