    15	  // a slower, older response must not overwrite a newer one.
    16	  let fetchSeq = 0
    17	
    18	  async function fetchSales(): Promise<void> {
    19	    const seq = ++fetchSeq
    20	    const list = await api.listSales()
    21	    if (seq !== fetchSeq) return
    22	    sales.value = list
    23	    serverOffset.value =
    24	      list.length > 0 ? Date.now() - Date.parse(list[0]!.server_now) : null
    25	  }
