    33	  // it events directly and assert the resulting state — the SSE wiring just
    34	  // routes into it. The payload is not needed: stock/sale changes always
    35	  // refetch the whole list.
    36	  async function applyEvent(event: RealtimeEvent): Promise<void> {
    37	    if (event !== 'stock_changed' && event !== 'sale_status') return
    38	    try {
    39	      await fetchSales()
    40	    } catch {
    41	      // A transient refetch failure is not worth surfacing; the next event or a
    42	      // reconnect will retry.
    43	    }
    44	  }
