    46	  let bound = false
    47	  function bindRealtime(): void {
    48	    if (bound) return
    49	    bound = true
    50	    const rt = useRealtime()
    51	    rt.on('stock_changed', () => void applyEvent('stock_changed'))
    52	    rt.on('sale_status', () => void applyEvent('sale_status'))
