    52	  reserveError.value = null
    53	  try {
    54	    await store.reserve(sale.id)
    55	  } catch (e) {
    56	    reserveError.value = e instanceof ApiError ? e.message : 'Could not reserve'
    57	  }
    58	}
    59	</script>
